"use client";

import {
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type FormEvent,
} from "react";
import { useRouter } from "next/navigation";
import { employeeAPI } from "@/externals/api-service";
import Link from "next/link";
import type { Employee, EmployeeInput } from "@/model/model";

type EmployeeFormValues = Omit<EmployeeInput, "salary"> & { salary: string };

export default function EmployeeForm({
  employee: initialEmployee,
}: {
  employee?: Employee;
}) {
  const router = useRouter();
  const submitting = useRef(false);
  const visible = useRef(true);
  const saved = useRef(false);
  const [employee, setEmployee] = useState<EmployeeFormValues>(() => ({
    name: initialEmployee?.name ?? "",
    department: initialEmployee?.department ?? "",
    salary: initialEmployee?.salary.toString() ?? "",
  }));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  useLayoutEffect(() => {
    visible.current = true;
    return () => {
      visible.current = false;
      setError("");
      if (saved.current) {
        saved.current = false;
        submitting.current = false;
        setSaving(false);
      }
    };
  }, []);

  function openSavedEmployee(id: number, message: string) {
    saved.current = true;
    if (visible.current) {
      router.replace(`/employees/${id}?message=${encodeURIComponent(message)}`);
    } else {
      saved.current = false;
      submitting.current = false;
      setSaving(false);
    }
  }

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    const { name, value } = event.currentTarget;
    setEmployee((current) => ({ ...current, [name]: value }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting.current) return;
    setError("");

    const { name, department, salary } = employee;
    const numericSalary = Number(salary);

    if (
      !name.trim() ||
      !department.trim() ||
      !salary.trim() ||
      !Number.isFinite(numericSalary) ||
      numericSalary < 0
    ) {
      setError("Enter a name, department, and a salary of zero or more.");
      return;
    }
    submitting.current = true;
    setSaving(true);
    const data: EmployeeInput = {
      name: name.trim(),
      department: department.trim(),
      salary: numericSalary,
    };

    try {
      if (initialEmployee) {
        const response = await employeeAPI.update(initialEmployee.id, data);
        openSavedEmployee(response.data.id, response.message);
      } else {
        const response = await employeeAPI.create(data);
        setEmployee({ name: "", department: "", salary: "" });
        openSavedEmployee(response.data, response.message);
      }
    } catch (error) {
      setError(
        error instanceof Error ? error.message : "Could not save the employee.",
      );
      submitting.current = false;
      setSaving(false);
    }
  }

  return (
    <form className="card form-card" onSubmit={handleSubmit} aria-busy={saving}>
      <div className="card-heading">
        <h2>Employee details</h2>
        <p className="muted">
          {initialEmployee
            ? `Employee ID: ${initialEmployee.id}`
            : "An employee ID will be generated when you save."}
        </p>
      </div>
      {error && (
        <p className="notice notice-error" role="alert">
          {error}
        </p>
      )}
      <fieldset disabled={saving} className="form-fields">
        <div className="field full-width">
          <label htmlFor="name">
            Full name <span className="required">*</span>
          </label>
          <input
            id="name"
            name="name"
            value={employee.name}
            onChange={handleChange}
            placeholder="e.g. Alex Morgan"
            autoComplete="name"
            required
          />
        </div>
        <div className="field">
          <label htmlFor="department">
            Department <span className="required">*</span>
          </label>
          <input
            id="department"
            name="department"
            value={employee.department}
            onChange={handleChange}
            placeholder="e.g. Engineering"
            required
          />
        </div>
        <div className="field">
          <label htmlFor="salary">
            Salary <span className="required">*</span>
          </label>
          <input
            id="salary"
            name="salary"
            type="number"
            value={employee.salary}
            onChange={handleChange}
            placeholder="e.g. 5000"
            min="0"
            step="0.01"
            required
          />
        </div>
      </fieldset>
      <div className="form-footer">
        <span className="field-hint">* Required fields</span>
        <div className="actions">
          {saving ? (
            <span className="button button-secondary" aria-disabled="true">
              Cancel
            </span>
          ) : (
            <Link href="/" className="button button-secondary">
              Cancel
            </Link>
          )}
          <button
            type="submit"
            className="button button-primary"
            disabled={saving}
          >
            {saving ? "Saving..." : initialEmployee ? "Save changes" : "Add employee"}
          </button>
        </div>
      </div>
    </form>
  );
}
